import React from 'react';
import './GoalProgress.css';

const GoalProgress = ({ goals }) => {
    if (!goals || goals.length === 0) {
        return (
            <div className="goal-progress empty">
                <h2>Goal Progress</h2>
                <p>No active goals.</p>
            </div>
        );
    }

    return (
        <div className="goal-progress">
            <h2>Goal Progress</h2>
            <div className="goals-list">
                {goals.map((goal) => (
                    <div 
                        key={goal.id} 
                        className={`goal-item ${goal.completed ? 'completed' : 'in-progress'}`}
                    >
                        <div className="goal-status-indicator"></div>
                        <div className="goal-content">
                            <div className="goal-description">{goal.description}</div>
                            <div className="goal-status">
                                Status: {goal.completed ? 'Completed' : 'In Progress'}
                            </div>

                            {goal.sub_goals && goal.sub_goals.length > 0 && (
                                <div className="sub-goals">
                                    <h4>Sub-goals:</h4>
                                    <ul>
                                        {goal.sub_goals.map((subGoal) => (
                                            <li 
                                                key={subGoal.id}
                                                className={subGoal.completed ? 'completed' : ''}
                                            >
                                                {subGoal.description}
                                                {subGoal.completed && <span className="check-mark">✓</span>}
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default GoalProgress;
